values('project-programme-portfolio-02','project-programme-portfolio',1,'1.5','There is insufficient specialist capacity to fund every proposed change initiative. Which decision most clearly belongs at portfolio level?','[{"id":"a","text":"Choose and balance investments against strategy and available capacity."},{"id":"b","text":"Assign tomorrow’s testing tasks inside one project."},{"id":"c","text":"Accept an individual deliverable against its specification."},{"id":"d","text":"Resolve a spelling error in a project report."}]'::jsonb,'a','Portfolio management concerns which investments should proceed and how the overall mix supports strategy and capacity. The other decisions concern delivery or administration within individual projects.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
