values('project-life-cycles-02','project-life-cycles',1,'2.4','Why would an extended life-cycle view continue beyond handover of equipment?','[{"id":"a","text":"To prevent operational owners taking responsibility."},{"id":"b","text":"To keep every temporary project team member employed indefinitely."},{"id":"c","text":"To avoid defining acceptance criteria."},{"id":"d","text":"To consider adoption, outcomes and benefits after outputs enter use."}]'::jsonb,'d','Value may arise after handover and needs operational ownership and review. An extended view does not remove acceptance criteria or imply that the temporary delivery team continues forever.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('project-life-cycles-03','project-life-cycles',1,'2.2','Which feature best characterises iterative delivery?','[{"id":"a","text":"No initial direction and no decisions about constraints."},{"id":"b","text":"Repeated development and review that use feedback to refine the work."},{"id":"c","text":"A ban on engaging users until everything is finished."},{"id":"d","text":"A guarantee that no requirement will change."}]'::jsonb,'b','Iteration creates opportunities to learn and refine through repeated cycles. It still needs direction, constraints and governance. Delaying all feedback or assuming fixed detailed requirements defeats that learning purpose.')
