insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('project-management-plan-01','project-management-plan',1,'4.1','A manager replaces the approved deployment baseline with the latest forecast without authorisation. What is the main problem?','[{"id":"a","text":"Forecasts must never be updated."},{"id":"b","text":"The project can no longer hold team meetings."},{"id":"c","text":"The reference for assessing variance and controlling change has been lost."},{"id":"d","text":"The business case automatically becomes a work breakdown structure."}]'::jsonb,'c','A baseline is an authorised control reference, while a forecast is the current expectation. Forecasts should be updated honestly; baseline changes need the agreed authority. Neither meeting arrangements nor document renaming addresses the control problem.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('project-management-plan-02','project-management-plan',1,'4.3','Which group should contribute to or be considered when developing a project management plan?','[{"id":"a","text":"Relevant sponsor, delivery, user, operational and supplier stakeholders."},{"id":"b","text":"Only the person who formats the schedule."},{"id":"c","text":"Only people who have no involvement in acceptance."},{"id":"d","text":"Every external person must approve every plan detail."}]'::jsonb,'a','The plan depends on stakeholder assumptions, constraints, responsibilities and acceptance needs. Involvement should be relevant and proportionate; it does not mean everyone approves everything or that planning is only document formatting.')
