insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('stakeholder-engagement-01','stakeholder-engagement',1,'4.6','An affected passenger group has little formal influence over a station redesign. What should the manager do?','[{"id":"a","text":"Exclude the group because only funding authority matters."},{"id":"b","text":"Assess its needs and impacts and choose proportionate engagement."},{"id":"c","text":"Assume a general announcement provides all necessary engagement."},{"id":"d","text":"Ask the group to approve the supplier’s entire commercial contract."}]'::jsonb,'b','Stakeholder analysis considers effects and needs as well as formal influence. The group may hold valuable information or need an accessible involvement route. Neither exclusion nor inappropriate approval duties follows from its low formal power.')
